<script setup>
import { ref, watch } from 'vue'
import { http, unwrap, errorMessage } from '../services/http.js'
import { canArea } from '../services/access.js'
import { getStoredUser } from '../services/tokens.js'
import SiteDocumentFrame from './SiteDocumentFrame.vue'
const props = defineProps({ ids: { type: Array, default: () => [] } })
const items = ref([]), dialog = ref(false), content = ref(null), error = ref(''), device = ref('desktop')
let version = 0
watch(() => props.ids.join(','), async () => { const current = ++version; items.value = []; if (!props.ids.length) return; try { const data = unwrap(await http.get('/site-templates/links', { params: { ids: [...new Set(props.ids)].slice(0,20).join(',') } })); if (current===version) items.value=data.items } catch { /* A removed site must not block a dispatch. */ } }, { immediate:true })
async function preview(item) { dialog.value=true; content.value=null;error.value='';try{content.value=unwrap(await http.get('/site-templates/'+item.id+'/preview'))}catch(cause){error.value=errorMessage(cause)} }
</script>
<template><section v-if="items.length" class="linked-sites"><strong><q-icon name="public"/> Sites vinculados</strong><div class="linked-sites-grid"><article v-for="item in items" :key="item.id"><span>{{item.name}}</span><small>{{!item.active||item.expired?'Fora do ar':item.visibility==='private'?'Privado · exige destinatário autorizado':'Público'}}<template v-if="item.expiresAt"> · {{new Date(item.expiresAt).toLocaleString('pt-BR')}}</template></small><div><q-btn v-if="canArea(getStoredUser(),'templates')" flat dense no-caps color="purple" icon="visibility" label="Prévia" @click="preview(item)"/><q-btn flat dense no-caps color="purple" icon="open_in_new" label="Abrir site" :href="item.url" target="_blank" rel="noopener noreferrer"/></div></article></div><q-dialog v-model="dialog" :maximized="$q.screen.lt.md"><q-card class="linked-site-dialog"><q-card-section class="row items-center"><strong class="col">Prévia do site</strong><q-btn-toggle v-model="device" flat dense :options="[{label:'Desktop',value:'desktop',icon:'computer'},{label:'Celular',value:'mobile',icon:'smartphone'}]"/><q-btn flat round icon="close" v-close-popup/></q-card-section><q-banner v-if="error" class="bg-red-1">{{error}}</q-banner><div class="linked-site-device" :class="{'linked-site-device--mobile':device==='mobile'}"><SiteDocumentFrame :content="content" compact/></div></q-card></q-dialog></section></template>
<style scoped>.linked-sites{padding:14px;border:1px solid #dcc8ef;border-radius:14px;margin:12px 0;background:#fbf7ff}.linked-sites>strong{font-size:13px;color:#7640a0;display:flex;align-items:center;gap:8px}.linked-sites-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px;margin-top:10px}.linked-sites article{min-width:0;padding:12px;background:white;border-radius:10px;border:1px solid #e9deee}.linked-sites article span,.linked-sites small{display:block;overflow-wrap:anywhere}.linked-sites article span{font-size:13px;font-weight:700}.linked-sites small{font-size:11px;color:#7a7181;margin:6px 0}.linked-site-dialog{width:1000px;max-width:96vw;border-radius:18px;max-height:94dvh;overflow:auto}.linked-site-device{padding:10px}.linked-site-device--mobile{max-width:410px;margin:auto}</style>
